// Parameters for the studio call. With the manual trigger these defaults are used;
// a POST to /webhook/visual-studio-test with any of CONTENT / ASSET_TYPES /
// FEEDBACK / FORCE / STYLE overrides them.
const body = ($input.first().json || {}).body || {};

// The default is the cheap path: one Gemini image, no composer turn. Set ASSET_TYPES
// to 'animation' or 'animation_linkedin' to exercise the composer, and FORCE to pin
// the form (auto|diagram|story|data|poster|image). STYLE is a brand scheme.
const DEFAULT_TYPES = 'image';

return [{
  json: {
    CONTENT: body.CONTENT ?? 'The homelab runs a small data platform across four machines. Ingest lands raw files in bronze, dbt builds the silver and gold tables in Iceberg, and Trino serves the dashboards that sit on top of them.',
    ASSET_TYPES: body.ASSET_TYPES ?? DEFAULT_TYPES,
    FEEDBACK: body.FEEDBACK ?? '',
    FORCE: body.FORCE ?? 'auto',
    STYLE: body.STYLE ?? ''
  }
}];

// One output item per asset: the summary, the asset itself as binary (preview in the
// execution view), and what the File Webhook needs to serve it as a download.
const r = $input.first().json;
const assets = r.ASSETS || [];
const ext = (ct) => (ct === 'image/gif' ? 'gif' : ct === 'image/webp' ? 'webp' : ct === 'video/mp4' ? 'mp4' : 'png');

if (!assets.length) {
  return [{ json: { RUN_ID: r.RUN_ID, RUN_STATUS: r.STATUS, NOTE: 'the studio returned no assets' } }];
}

return assets.map((a) => {
  const frames = Number(a.FRAME_COUNT) || 1;
  const pixels = a.WIDTH && a.HEIGHT ? Number(a.WIDTH) * Number(a.HEIGHT) * frames : 0;
  const dataUrl = String(a.IMAGE || '');
  const base64 = dataUrl.startsWith('data:') ? dataUrl.slice(dataUrl.indexOf(',') + 1) : '';

  const json = {
    RUN_ID: r.RUN_ID,
    RUN_STATUS: r.STATUS,
    ASSET_TYPE: a.ASSET_TYPE,
    STATUS: a.STATUS,
    FORMAT: a.FORMAT,
    CONTENT_TYPE: a.CONTENT_TYPE || '',
    DURATION_MS: a.DURATION_MS || '',
    FRAME_COUNT: a.FRAME_COUNT || '',
    WIDTH: a.WIDTH || '',
    HEIGHT: a.HEIGHT || '',
    TOTAL_PIXELS: pixels || '',
    LINKEDIN_GIF_CAP_OK: a.CONTENT_TYPE === 'image/gif' ? (frames <= 500 && pixels <= 36152320) : undefined,
    IMAGE_BYTES: a.IMAGE ? Math.floor((String(a.IMAGE).length - String(a.IMAGE).indexOf(',') - 1) * 3 / 4) : 0,
    STORYBOARD: a.STORYBOARD || '',
    ERROR: a.ERROR || '',
    FILE_ID: a.ASSET_TYPE + '_' + r.RUN_ID,
    FILE_EXT: ext(a.CONTENT_TYPE),
    DATA_BASE64: base64
  };

  const item = { json };
  if (dataUrl.startsWith('data:')) {
    item.binary = {
      data: {
        data: Buffer.from(base64, 'base64'),
        mimeType: a.CONTENT_TYPE,
        fileName: a.ASSET_TYPE + '.' + ext(a.CONTENT_TYPE),
        fileExtension: ext(a.CONTENT_TYPE)
      }
    };
  }
  return item;
});

// Turn each asset into a clickable download URL. The bytes live in the TemporalFiles
// DataTable and are served by the File Webhook, which deletes rows older than 1 hour.
// The served shape is /webhook/<webhookId>/<path-with-param>, verified 2026-10-01
// (a one-segment URL, /webhook/<webhookId>/<fileId>, returns 404).
const BASE = 'https://automation-n8n.homelab.alvsanand.com/webhook/76a3521f-8ce6-41e5-9741-a1a0d22736ff/76a3521f-8ce6-41e5-9741-a1a0d22736ff/';
const items = $('unpack_assets').all();

return items.map((it) => {
  const json = Object.assign({}, it.json);
  delete json.DATA_BASE64;
  json.FILE_NAME = json.ASSET_TYPE + '.' + json.FILE_EXT;
  json.DOWNLOAD_URL = BASE + encodeURIComponent(json.FILE_ID);
  json.DOWNLOAD_NOTE = 'link expires about an hour after the run';
  return { json, binary: it.binary };
});

// One item for the HTTP response, so every asset's link arrives together: responseMode
// lastNode answers with the first item only, which hid all but the first asset.
const items = $('download_url').all();
const first = items[0].json;
return [{
  json: {
    RUN_ID: first.RUN_ID,
    RUN_STATUS: first.RUN_STATUS,
    ASSET_COUNT: items.length,
    ASSETS: items.map((i) => i.json)
  }
}];

